$animSource = [IO.File]::ReadAllText((Join-Path $StageRoot 'src\animation\AnimManager.cpp'))
$arrays = [regex]::Matches($animSource, '(?ms)^char const\s*\*\s*aPlayer(?:WithRocket|1Armed|2Armed|BBBat|StrafeBack|StrafeLeft|StrafeRight)?Animations\[\] = \{.*?^\};')
if ($arrays.Count -ne 8) { throw 'Cannot extract eight forward/strafe/back movement animation mappings.' }
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'quest-sprint-anims.inc'), $enum.Value + "`n" + (($arrays | ForEach-Object { $_.Value }) -join "`n"), [Text.UTF8Encoding]::new($false))
Copy-Item -LiteralPath (Join-Path $StageRoot 'src\weapons\WeaponType.h') -Destination (Join-Path $PSScriptRoot 'quest-sprint-weapon-types.inc')
Write-Host ('PlayerPed.cpp SHA256: ' + (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-quest-sprint.cpp')

#!/usr/bin/env python3
"""Verify the production radio/driving/firing boundary without game assets."""
from pathlib import Path
import re
import subprocess
import tempfile
root=Path(__file__).resolve().parents[2]
driving=(root/'overlay/src/vr/QuestDrivingVR.cpp').read_text()
weapons=(root/'overlay/src/vr/QuestWeaponVR.cpp').read_text()
def method(text,name):
    match=re.search(r'(?ms)^(?:static )?(?:void|uint32)\s+'+name+r'\(.*?^}',text)
    assert match,name
    return match.group()
code='\n'.join(method(driving,n) for n in ['MapButtonDriveBy','UpdateQuestDrivingInput','ApplyQuestVehicleButtonInput'])
code+='\n'+method(weapons,'UpdateWeaponTriggerEdges')
call=re.search(r'(?s)if\(inVehicle\)\s*UpdateWeaponTriggerEdges\([^;]+;',weapons).group()
code+='\nvoid ProductionFireEdgeGate(bool menu,bool gameplay,uint32 vehicleCapturedHands,bool inVehicle,const androidgame::PadInput &input){'+call+'}\n'
with tempfile.TemporaryDirectory(prefix='radio-driving-') as d:
    work=Path(d);(work/'production.inc').write_text(code)
    (work/'main.cpp').write_text(r'''
#include <cassert>
#include <cstdio>
#include <cstdint>
#include <algorithm>
#define nil nullptr
using uint32=uint32_t;using int16=int16_t;
constexpr int VR_HAND_COUNT=2;
template<class T,class U,class V>T clamp(T v,U a,V b){return std::max(T(a),std::min(v,T(b)));}
struct CControllerState {int Square=0,Cross=0,Circle=0,LeftShoulder1=0,RightShoulder1=0,LeftShoulder2=0,RightShoulder2=0;void Clear(){*this={};}};
struct CVehicle {void*pDriver=nullptr;bool IsRealHeli(){return false;}bool IsRealPlane(){return false;}bool IsCar(){return true;}bool IsBike(){return false;}} vehicle;
int player;CVehicle*FindPlayerVehicle(){return &vehicle;}void*FindPlayerPed(){return &player;}
struct CPad {int GetMode(){return 0;}static CPad*GetPad(int){static CPad pad;return &pad;}};
namespace androidgame {struct PadInput{bool x=false,b=false,a=false;float leftTrigger=0,rightTrigger=0,leftGrip=0,rightGrip=0;}input;const PadInput&GetPadInput(){return input;}}
namespace QuestRadio {bool active=false;bool Update(bool blocked){if(blocked)active=false;return false;}bool Interacting(){return active;}void SuppressDriving(CControllerState*s){if(active)s->Clear();}}
namespace OculusVR {
CVehicle*gButtonDriveByVehicle=nullptr;int gButtonDriveByDirection=-1;
bool gVehicleForwardFireEnabled=true,gVrRadioChangeJustPressed=false;
bool physical=false;uint32 bikeBlocked=0,carBlocked=0;bool motionBlocked=false;
bool gPoseValid[2]={true,true},gTriggerPressed[2]={},gTriggerJustPressed[2]={},gTriggerJustReleased[2]={};
float gTrigger[2]={};int gHeldSlot[2]={-1,-1};
constexpr int VR_DRIVING_DEFAULT=0;int GetDrivingTypeForVehicle(CVehicle*){return physical?1:0;}
void LoadDrivingSettings(){}bool IsVrDrivingActive(){return physical;}bool IsImmersiveDrivingActive(){return physical;}bool IsTrackedWeaponHeld(int h){return gHeldSlot[h]>=0;}
bool IsQuestVehicleThirdPerson(){return false;}bool IsVrCarActive(){return physical;}bool IsVrBikeActive(){return false;}bool IsQuestDrivingHandUnavailable(int){return false;}
uint32 UpdateImmersiveBikeInput(const float*,const androidgame::PadInput&,uint32 blocked){bikeBlocked=blocked;return 0;}
uint32 UpdateImmersiveCarInput(const float*,uint32 blocked){carBlocked=blocked;return 0;}
void UpdateMotionInput(const androidgame::PadInput&,bool blocked){motionBlocked=blocked;}
void MapHornToPad(CControllerState*){}void MapHandbrakeToPad(CControllerState*s,bool on){if(on)s->LeftShoulder1=255;}
#include "production.inc"
}
int main(){
 using namespace OculusVR;vehicle.pDriver=&player;auto &input=androidgame::input;CControllerState state;
 input.rightTrigger=.8f;input.leftTrigger=.6f;input.b=true;
 assert(UpdateQuestDrivingInput(&state,false)==0);ApplyQuestVehicleButtonInput(&state,false);
 assert(state.Cross>0 && state.Square>0 && gButtonDriveByVehicle==&vehicle);
 QuestRadio::active=true;assert(UpdateQuestDrivingInput(&state,false)==3);
 assert(bikeBlocked==3 && carBlocked==3 && motionBlocked);
 ApplyQuestVehicleButtonInput(&state,false);
 assert(state.Cross==0 && state.Square==0 && state.Circle==0 && gButtonDriveByVehicle==nullptr);
 physical=true;gHeldSlot[1]=2;
 ProductionFireEdgeGate(false,true,3,true,input);assert(!gTriggerPressed[1] && !gTriggerJustPressed[1]);
 QuestRadio::active=false;UpdateQuestDrivingInput(&state,false);ApplyQuestVehicleButtonInput(&state,false);
 ProductionFireEdgeGate(false,true,3,true,input);assert(gTriggerPressed[1] && gTriggerJustPressed[1]);
 assert(state.Cross>0 && !motionBlocked);
 ProductionFireEdgeGate(true,true,0,true,input);assert(!gTriggerPressed[1]);
 puts("Production driving integration: radio captures throttle/brake, wheel/motion input and both native/physical firing; ordinary input restores correctly.");
}
''')
    exe=work/'test';subprocess.run(['c++','-std=c++17',str(work/'main.cpp'),'-o',str(exe)],check=True)
    subprocess.run([str(exe)],check=True)

#!/usr/bin/env python3
"""Exercise production radio input with deterministic poses and clock."""
from pathlib import Path
import re
import subprocess
import tempfile
root=Path(__file__).resolve().parents[2]
source=(root/'overlay/src/vr/QuestRadio.cpp').read_text()
production=[]
for name in ['Update','SuppressDriving']:
    match=re.search(r'(?ms)^bool Update\(.*?^}',source) if name=='Update' else re.search(r'(?m)^void SuppressDriving[^\n]+',source)
    assert match, name
    production.append(match.group())
with tempfile.TemporaryDirectory(prefix='radio-input-') as d:
    work=Path(d)
    (work/'production.inc').write_text('\n'.join(production))
    (work/'main.cpp').write_text(r'''
#include "RadioBoardLayout.h"
#include <cassert>
#include <cstdio>
#include <cstring>
#include <cstdint>
struct CVector { float x,y,z; CVector(float a=0,float b=0,float c=0):x(a),y(b),z(c){} CVector operator-(CVector b) const{return {x-b.x,y-b.y,z-b.z};} };
float DotProduct(CVector a,CVector b){return a.x*b.x+a.y*b.y+a.z*b.z;}
namespace androidgame {
struct PadInput { struct Pose {float position[3],orientation[4];bool valid=false;}; Pose aimPose[2]; bool x=false; float leftTrigger=0,rightTrigger=0; } input;
const PadInput &GetPadInput(){return input;}
}
namespace OculusVR { bool weapon=false; bool IsTrackedWeaponHeld(int){return weapon;} bool GetTrackedIndexTip(int,CVector*){return false;} }
namespace rw { namespace vulkan {
bool playPoseToFirstPersonWorld(const float *pos,const float*,float*,float*,float *forward,float *origin){memcpy(origin,pos,12);forward[0]=forward[1]=0;forward[2]=-1;return true;}
} }
struct CControllerState { int acceleration=255; void Clear(){acceleration=0;} };
namespace QuestRadio {
struct Plane{CVector origin,right={1,0,0},up={0,1,0},normal={0,0,1};float width=.4f;};
bool available=true,vehicle=true,interacting=false,xDown=false,triggerDown[2]={true,true};
bool touchMode=false; RadioBoard::Touch touch[2];
int hover=-1,activations=0,last=-1;double now=0,xSince=0;
void Load(){} bool BuildPlane(Plane &){return available;} bool Vehicle(){return vehicle;} double Now(){return now;}
void Activate(int hit){++activations;last=hit;}
#include "production.inc"
}
int main(){
 using namespace QuestRadio; auto &in=androidgame::input;
 assert(!Update(false)); in.x=true; now=.01; assert(!Update(false));
 in.x=false; now=.1; assert(Update(false)); // ordinary short station tap
 in.x=true; now=1; assert(!Update(false)); now=1.31; assert(!Update(false) && interacting);
 // Aim at NEXT, but a trigger already held for driving must not click.
 in.aimPose[0].valid=true;in.aimPose[0].position[0]=(422-256)*.4f/512;in.aimPose[0].position[1]=(128-159)*.4f/512;in.aimPose[0].position[2]=1;
 in.leftTrigger=1; Update(true); now=2; Update(false); now=2.31; Update(false); assert(activations==0);
 in.leftTrigger=0; Update(false);in.leftTrigger=1;Update(false);assert(activations==1 && last==6);
 Update(false);assert(activations==1); // no repeat while held
 CControllerState pad;SuppressDriving(&pad);assert(pad.acceleration==0);
 in.x=false;now=2.5;assert(!Update(false));assert(!interacting);
 pad.acceleration=255;SuppressDriving(&pad);assert(pad.acceleration==255);
 // Invalid tracking, weapon ownership and blocked/menu frames never activate.
 in.x=true;now=3;Update(false);now=3.4;Update(false);
 in.leftTrigger=0;Update(false);in.aimPose[0].valid=false;in.leftTrigger=1;Update(false);assert(activations==1);
 in.aimPose[0].valid=true;in.leftTrigger=0;Update(false);OculusVR::weapon=true;in.leftTrigger=1;Update(false);assert(activations==1);
 Update(true);assert(!interacting);
 puts("Production radio input: tap/hold, pointer click, held-trigger gating, tracking, weapon exclusion and driving capture passed.");
}
''')
    exe=work/'test'
    subprocess.run(['c++','-std=c++17','-I'+str(root/'overlay/src/vr'),str(work/'main.cpp'),'-o',str(exe)],check=True)
    subprocess.run([str(exe)],check=True)

param(
    [string]$KitRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$OutDir=(Join-Path ([IO.Path]::GetTempPath()) ('lcvr-radio-touch-'+[guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$radio=[IO.File]::ReadAllText((Join-Path $KitRoot 'overlay/src/vr/QuestRadio.cpp'))
$code='#include "'+((Join-Path ([IO.Path]::GetFullPath($KitRoot)) 'overlay/src/vr/RadioBoardLayout.h').Replace('\','/'))+'"'+"`n"
$code+="namespace QuestRadio {`n"
foreach($name in @('Update','SuppressDriving','MenuRow','MenuAction')) {
    $match=[regex]::Match($radio,'(?m)^(?:void|bool) '+$name+'\(')
    if(-not $match.Success){throw "Missing production function: $name"}
    $open=$radio.IndexOf('{',$match.Index);$depth=0
    for($i=$open;$i -lt $radio.Length;$i++) {
        if($radio[$i] -eq '{'){$depth++}
        if($radio[$i] -eq '}'){$depth--;if($depth -eq 0){break}}
    }
    if($depth -ne 0){throw "Unterminated production function: $name"}
    $code+=$radio.Substring($match.Index,$i-$match.Index+1)+"`n"
}
$code+="}`n"
$hand=[IO.File]::ReadAllText((Join-Path $KitRoot 'overlay/src/vr/VRHandModel.cpp'))
$code+="namespace VRHandModel {`n"
foreach($name in @('Clamp01','InterpolatePose','IndexTip')) {
    $match=[regex]::Match($hand,'(?ms)^(?:float|CVector|bool)\r?\n'+$name+'\(.*?^}')
    if(-not $match.Success){throw "Missing production hand function: $name"}
    $code+=$match.Value+"`n"
}
$code+="}`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'radio-touch-production.inc'),$code,[Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $KitRoot -OutDir $OutDir -Sources @('test-radio-touch.cpp')
if($LASTEXITCODE -ne 0){throw 'Radio touch regression failed'}

param(
