 $start=$source.IndexOf('{',$match.Index);$end=$start+1;$depth=1
 while($depth-gt0-and$end-lt$source.Length){if($source[$end]-eq'{'){$depth++}elseif($source[$end]-eq'}'){$depth--};$end++}
 if($mode-eq'Write'){
  $tail=[regex]::Match($source.Substring($end),'^\s*ApplyPresentation\(mats,rig.pose.count,presentation\);')
  if(-not$tail.Success){throw 'Raw pose cache must be written before presentation'}
  $end+=$tail.Length
 }
 $parts.Add('static void ProductionCache'+$mode+'(Slot*slot,RwMatrix*mats,int count) {'+"`n"+'struct {int numNodes;} hierarchy={count}; const auto*hier=&hierarchy; const auto presentation=Presentation(slot);'+"`n"+($source.Substring($match.Index,$end-$match.Index).Replace('rig.pose.count','hier->numNodes').Replace('VrRagdollRig::Write(ped,rig,mats);',''))+"`n}")
}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'ragdoll-presentation-production.inc'),($parts-join"`n"),[Text.UTF8Encoding]::new($false))
