param(
 [string]$StageRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
 [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('vc-entry-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$src=Join-Path $StageRoot 'src'
if(-not(Test-Path -LiteralPath $src)){$src=Join-Path $StageRoot 'overlay/src'}
$ped=[IO.File]::ReadAllText((Join-Path $src 'peds/Ped.cpp'))
$ai=[IO.File]::ReadAllText((Join-Path $src 'peds/PedAI.cpp'))
$prologue=[regex]::Match($ped,'(?ms)(?<=CPed::ProcessControl\(void\)\r?\n\{\r?\n).*?(?=\tCColPoint foundCol;)').Value
if($prologue -notmatch 'vrEntryCancelInput.Update'){throw 'Missing production Quest entry observer.'}
$cancel=[regex]::Match($ped,'(?ms)^#ifdef CANCELLABLE_CAR_ENTER\r?\n\s*static bool cancelJack.*?^#endif(?=\r?\n\r?\n\s*switch \(m_nPedState\))').Value
if(-not $cancel){throw 'Missing production cancellation block.'}
$production='void CPed::ProcessEntryCancellation() {'+"`n"+$prologue+$cancel+"`n}`n"
# The exact former block supplies an executable regression demonstration.
$baseline=Join-Path $StageRoot 'baseline-qbuild/src/peds/Ped.cpp'
if(Test-Path -LiteralPath $baseline){
 $baselineText=[IO.File]::ReadAllText($baseline)
 $old=[regex]::Match($baselineText,'(?ms)^#ifdef CANCELLABLE_CAR_ENTER\r?\n\s*static bool cancelJack.*?^#endif(?=\r?\n\r?\n\s*switch \(m_nPedState\))').Value
 if(-not $old){throw 'Missing baseline cancellation block.'}
 $production+='void CPed::ProcessBaselineCancellation() {'+"`n"+$old+"`n}`n"
 $preserved=$ped.Replace($prologue,'').Replace($cancel,$old)
 $preserved=$preserved -replace '(?m)^#if defined\(__ANDROID__\) && defined\(GTA_VR_WEAPONS\) && defined\(CANCELLABLE_CAR_ENTER\)\r?\n#include "VrVehicleEntry.h"\r?\n#endif\r?\n',''
 if(($preserved -replace '\s','') -cne ($baselineText -replace '\s','')){throw 'Unexpected edit outside the Quest entry input gate.'}
 Write-Host 'Native Ped/ragdoll source preservation: PASS after removing only the new input gate.'
}else{
 # Public kits have no prior checkout. Retain an explicit baseline predicate
 # only for the old-behaviour demonstration; all fixed assertions use source.
 $old=$cancel -replace '(?ms)^#if defined\(__ANDROID__\) && defined\(GTA_VR_WEAPONS\)\r?\n\s*if \(vrCancelEntryMovement\) \{\r?\n#else\r?\n(.*?)^#endif','$1'
 $production+='void CPed::ProcessBaselineCancellation() {'+"`n"+$old+"`n}`n"
}
foreach($name in @('PedAnimAlignCB','PedAnimDoorOpenCB','PedAnimGetInCB','PedAnimDoorCloseCB')){
 $method=[regex]::Match($ai,'(?ms)^void\r?\nCPed::'+$name+'\([^\n]*\)\r?\n\{.*?^\}').Value
 if(-not $method){throw ('Missing native callback '+$name)}
 $production+=$method+"`n"
}
$enumNames=[regex]::Matches($production,'\b(?:ANIM_\w+|ASSOCGRP_\w+|PEDTYPE_\w+|PED_\w+|OBJECTIVE_\w+|VEHICLE_APPEARANCE_\w+|DOOR_STATUS_\w+|CARLOCK_\w+|CAR_DOOR_\w+|CAR_WINDSCREEN|STATUS_\w+|MISSION_\w+|SOUND_\w+)\b') | ForEach-Object {$_.Value}
$enumNames=@($enumNames)+@('STATUS_ABANDONED','CARLOCK_UNLOCKED','PEDTYPE_PLAYER1','PED_IDLE','PED_ENTER_CAR','CARLOCK_LOCKED','STATUS_WRECKED','ANIM_STD_CAR_ALIGN_DOOR_LHS') | Sort-Object -Unique
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'vr-vehicle-entry-enums.inc'),('enum { '+($enumNames -join ',')+' };'),[Text.UTF8Encoding]::new($false))
$header=[IO.Path]::GetFullPath((Join-Path $src 'peds/VrVehicleEntry.h')).Replace('\','/')
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'vr-vehicle-entry-production.inc'),$production,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'vr-vehicle-entry-helper.inc'),('#include "'+$header+'"'),[Text.UTF8Encoding]::new($false))
Write-Host ('Production Ped.cpp SHA256: '+(Get-FileHash -LiteralPath (Join-Path $src 'peds/Ped.cpp')).Hash)
Write-Host ('Production callbacks SHA256: '+(Get-FileHash -LiteralPath (Join-Path $src 'peds/PedAI.cpp')).Hash)
Write-Host ('Production input latch SHA256: '+(Get-FileHash -LiteralPath $header).Hash)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-vr-vehicle-entry.cpp')
if($LASTEXITCODE -ne 0){throw 'Quest vehicle entry test failed.'}

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-wheel-fps-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
$StageRoot = [IO.Path]::GetFullPath($StageRoot)
$OutDir = [IO.Path]::GetFullPath($OutDir)
function Extract-Block([string]$text, [string]$pattern) {
    $match = [regex]::Match($text, $pattern)
    if (-not $match.Success) { throw "Missing production definition: $pattern" }
    $end = $match.Index + $match.Length; $depth = 1
    while ($depth -gt 0 -and $end -lt $text.Length) {
        if ($text[$end] -eq '{') { $depth++ }
        elseif ($text[$end] -eq '}') { $depth-- }
        $end++
    }
    if ($depth -ne 0) { throw 'Unterminated production definition.' }
    $text.Substring($match.Index, $end - $match.Index)
}
$physical = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.cpp'))
$header = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.h'))
$vehicle = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Vehicle.cpp'))
$auto = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Automobile.cpp'))
$config = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/core/config.h'))
$output = [regex]::Match($header, '(?m)^#define GRAVITY[^\r\n]+').Value + "`n"
if ([regex]::IsMatch($config, '(?m)^\s*#\s*define FIX_SIGNIFICANT_BUGS\b')) { $output += "#define FIX_SIGNIFICANT_BUGS`n" }
foreach ($name in @('GetSpeed','ApplyMoveSpeed','ApplyMoveForce','ApplyTurnForce','ApplySpringCollision','ApplySpringDampening','ApplyGravity','ApplyAirResistance')) {
    $output += (Extract-Block $physical ('(?m)^(?:CVector|void|bool)\s+CPhysical::' + $name + '\([^)]*\)\s*\{')) + "`n"
}
$mass = Extract-Block $header 'float GetMass\([^)]*\)\s*\{'
$output += $mass.Replace('float GetMass', 'float CPhysical::GetMass') + "`n"
$constants = [regex]::Match($vehicle, '(?m)^float fBurstSpeedMax[^;]+;\s*float fBurstTyreMod[^;]+;')
if (-not $constants.Success) { throw 'Missing burst tyre constants.' }
$output += $constants.Value + "`n" + (Extract-Block $vehicle '(?m)^void\s+CVehicle::ProcessWheel\([^)]*\)\s*\{') + "`n"
$timer = [regex]::Match($auto, '(?s)if\(m_aSuspensionSpringRatio\[i\] < 1.0f\)\s*m_aWheelTimer\[i\] = 4.0f;\s*else\s*m_aWheelTimer\[i\] = Max\([^;]+;')
if (-not $timer.Success) { throw 'Missing wheel contact grace period.' }
$output += "static void ProductionContactTimer(float ratio, float &timer) { int i=0; float m_aSuspensionSpringRatio[1]={ratio}; float m_aWheelTimer[1]={timer};`n" + $timer.Value + "`ntimer=m_aWheelTimer[0]; }`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'wheel-suspension-fps-production.inc'), $output, [Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-wheel-suspension-fps.cpp')
if ($LASTEXITCODE -ne 0) { throw 'Wheel fixture compilation/smoke checks failed.' }
$exe = Join-Path $OutDir 'test-wheel-suspension-fps.exe'
$rows = [Collections.Generic.List[string]]::new()
$rows.Add('scenario,fps,pacing,wall_s,sim_s,stop_s,distance_m,forward_mps,lateral_mps,heading_deg,min_height_m,max_height_m,peak_vertical_mps,skid_fraction,locked_fraction,sign_reversals,contact_grace_ms,final_height_m,residual_vertical_span_m')
foreach ($scenario in @('brake','coast','lateral','steer','drop','bump','grace','history-clean','history-primed')) {
    foreach ($fps in @(15,18,20,30,36,60,72,80,90,120,144)) {
        foreach ($pacing in @('steady','jitter','stall')) {
            # Fresh process: native ProcessWheel statics must not leak between
            # scenarios/frame rates. The history pair intentionally probes them.
            $line = & $exe $scenario $fps $pacing
            if ($LASTEXITCODE -ne 0) { throw "Failed: $scenario $fps $pacing" }
            $rows.Add(($line -join ''))
        }
    }
}
[IO.File]::WriteAllLines((Join-Path $OutDir 'measurements.csv'), $rows)
$hashes = @('src/entities/Physical.cpp','src/entities/Physical.h','src/vehicles/Vehicle.cpp','src/vehicles/Automobile.cpp','src/core/config.h') | ForEach-Object {
    Get-FileHash -LiteralPath (Join-Path $StageRoot $_) | Select-Object Path,Hash
}
$hashes | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $OutDir 'source-hashes.json')
Write-Host ('PASS: ' + ($rows.Count-1) + ' isolated controlled-rate scenarios; measurements: ' + (Join-Path $OutDir 'measurements.csv'))

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path $env:TEMP ('lcvr-billboards-' + [guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$kitRoot=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$kitHeader=Join-Path $kitRoot 'overlay/src/renderer/QuestBillboard.h'
$stageHeader=Join-Path $StageRoot 'src/renderer/QuestBillboard.h'
if((Get-FileHash $kitHeader).Hash -ne (Get-FileHash $stageHeader).Hash){
    throw 'Assembled billboard helper differs from the production header under test.'
}
$sprite=Get-Content -Raw (Join-Path $StageRoot 'src/renderer/Sprite.cpp')
$world=$sprite.Substring(0,$sprite.IndexOf('CSprite::Set6Vertices2D'))
if($world -notmatch 'window->x, window->y, worldUp, worldEast' -or
   $world -notmatch 'worldUp\[3\] = \{ -camera->right.z, camera->up.z, camera->at.z \}'){
    throw 'Billboards must receive world axes expressed in the actual render camera frame.'
}
if(([regex]::Matches($world,'FaceQuestWorldSprite\((?:vert|verts), [46], x, y\);')).Count -ne 6){
    throw 'All six world sprite routines must orient the complete quad.'
}
if(([regex]::Matches($world,'if\(!QuestWorldBillboardsEnabled\(\)\)')).Count -ne 6){
    throw 'Legacy mono clipping must be bypassed before stereo reorientation.'
}
if($sprite.Substring($sprite.IndexOf('CSprite::Set6Vertices2D')) -match 'FaceQuestWorldSprite'){
    throw 'Screen-space sprites must retain their original geometry.'
}
if($world -notmatch 'return !androidgame::VrShouldUseTheaterMode\(\);'){
    throw 'The mono theater path must retain its existing projection.'
}
$shader=Get-Content -Raw (Join-Path $StageRoot 'vendor/librw/src/vulkan/shaders/rw_im2d.vert')
$clouds=Get-Content -Raw (Join-Path $StageRoot 'src/renderer/Clouds.cpp')
if($clouds -notmatch '(?s)if\(!androidgame::VrShouldUseTheaterMode\(\)\)\{\s*CClouds::ms_cameraRoll = 0.0f;\s*return;'){
    throw 'Clouds must not apply the old camera-roll correction over the world-oriented billboard.'
}
if($shader -notmatch 'worldBillboard \? inPosition.w : max\(inPosition.w, panel\)'){
    throw 'Near world sprites must not be clamped to the HUD plane.'
}
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -OutDir $OutDir -Sources @('test-world-billboards.cpp')
if($LASTEXITCODE -ne 0){ throw 'Billboard geometry tests failed.' }

param(
    [Parameter(Mandatory=$true)][ValidateSet('Record','Replay','Stop','Status','Pull')][string]$Action,
    [Parameter(Mandatory=$true)][string]$Serial,
    [ValidatePattern('^[A-Za-z0-9_-]{1,32}$')][string]$Label='trial',
    [ValidateRange(1,120)][int]$Seconds=30,
    [string]$OutDir,
    [string]$Adb='adb'
)
$ErrorActionPreference='Stop'
$remote='/sdcard/Android/data/com.libertyvr.quest/files/vehicle-capture'
function Invoke-Adb([string[]]$Arguments){
    $result=& $Adb -s $Serial @Arguments
    if($LASTEXITCODE-ne0){throw "ADB command failed: $($Arguments[0])"}
    $result
}
$model=(Invoke-Adb -Arguments @('shell','getprop','ro.product.model') | Out-String).Trim()
if($model-ne'Quest 3'){throw "Expected a verified Quest 3; $Serial reports '$model'."}
if($Action-eq'Status'){Invoke-Adb -Arguments @('shell','cat',"$remote/status.txt");exit}
if($Action-eq'Pull'){$command='stop'}
elseif($Action-eq'Record'){$command="record $Label $Seconds"}
elseif($Action-eq'Replay'){$command="replay $Label"}
else{$command='stop'}
Invoke-Adb -Arguments @('shell','mkdir','-p',$remote) | Out-Null
$taskRoot=Split-Path $PSScriptRoot -Parent
$scratch=Join-Path $taskRoot '.cache/vehicle-capture-commands'
[void][IO.Directory]::CreateDirectory($scratch)
$local=Join-Path $scratch ([Guid]::NewGuid().ToString('N')+'.txt')
[IO.File]::WriteAllText($local,$command+"`n",[Text.UTF8Encoding]::new($false))
Invoke-Adb -Arguments @('push',$local,"$remote/control.pending") | Out-Null
Invoke-Adb -Arguments @('shell','mv',"$remote/control.pending","$remote/control.txt") | Out-Null
$deadline=[DateTime]::UtcNow.AddSeconds(6)
do{
    & $Adb -s $Serial shell test -e "$remote/control.txt"
    if($LASTEXITCODE-ne0){break}
    Start-Sleep -Milliseconds 250
}while([DateTime]::UtcNow-lt$deadline)
if([DateTime]::UtcNow-ge$deadline){throw 'Command remains pending: run a capture-enabled APK in unpaused gameplay. No input replay has been confirmed.'}
$status=(Invoke-Adb -Arguments @('shell','cat',"$remote/status.txt") | Out-String).Trim()
Write-Host $status
if($Action-eq'Pull'){
    if($status-ne'stopped'){throw 'Capture did not close cleanly; inspect status before pulling.'}
    if(-not$OutDir){$OutDir=Join-Path $taskRoot ('.cache/vehicle-traces/'+[DateTime]::Now.ToString('yyyyMMdd-HHmmss'))}
    if(Test-Path -LiteralPath $OutDir){throw 'Choose a new output directory.'}
    [void][IO.Directory]::CreateDirectory($OutDir)
    Invoke-Adb -Arguments @('pull',"$remote/.",[IO.Path]::GetFullPath($OutDir))
}elseif(($Action-eq'Record'-and$status-notin@('recording','duration complete'))-or($Action-eq'Replay'-and$status-notlike'replaying:*'-and$status-ne'replay complete')){
    throw "Requested $Action did not start: $status"
}

import contextlib
import importlib.util
import io
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch

spec = importlib.util.spec_from_file_location('bridge', Path(__file__).with_name('device_bridge.py'))
b = importlib.util.module_from_spec(spec)
spec.loader.exec_module(b)


class PackTests(unittest.TestCase):
    def test_validation_and_roundtrip(self):
        entries = {'xbox:95': {'WheelX': 2, 'DashFollowWheel': 0, 'MapPitch': 33, 'RadioX': 35, 'RadioRoll': -180, 'RadioSize': 125, 'SpeedometerX': 4, 'SpeedometerY': 8, 'SpeedometerZ': 22, 'SpeedometerPitch': -15, 'SpeedometerYaw': 20, 'SpeedometerRoll': -180, 'SpeedometerSize': 125}}
        self.assertEqual(b.parse(b.serialize(entries)), entries)
        for text in ('[Placement]\nVersion=2', '[Placement]\nVersion=1\n[xbox:95]\nWheelX=nan',
                     '[Placement]\nVersion=1\n[xbox:95]\nWheelVisible=.3',
                     '[Placement]\nVersion=1\n[xbox:95]\nWheelRadius=1',
                     '[Placement]\nVersion=1\n[xbox:95]\nUnknown=3',
                     '[Placement]\nVersion=1\n[xbox:95]\nSpeedometerSize=0',
                     '[Placement]\nVersion=1\n[xbox:95]\nSpeedometerPitch=181',
                     '[Placement]\nVersion=1\n[xbox:95]\nWheelX=1\nWheelX=2'):
            with self.assertRaises(b.BridgeError):
                b.parse(text)

    def test_preserve_unrelated_remote_changes(self):
        base = {'classic:95': {'WheelX': 0, 'WheelY': 0}, 'xbox:95': {'WheelX': 1}}
        remote = {'classic:95': {'WheelX': 0, 'WheelY': 9}, 'xbox:95': {'WheelX': 8}}
        local = {'classic:95': {'WheelX': 3, 'WheelY': 0}, 'xbox:95': {'WheelX': 1}}
        result, conflicts = b.merge(base, remote, local, ['classic:95'])
        self.assertEqual(result, {'classic:95': {'WheelX': 3, 'WheelY': 9}, 'xbox:95': {'WheelX': 8}})
        self.assertEqual(conflicts, [])

    def test_conflicts_and_resolution(self):
        base = {'xbox:95': {'WheelX': 0}}
        remote = {'xbox:95': {'WheelX': 1}}
        local = {'xbox:95': {'WheelX': 2}}
        with self.assertRaises(b.BridgeError):
            b.merge(base, remote, local, ['xbox:95'])
        self.assertEqual(b.merge(base, remote, local, ['xbox:95'], 'local')[0], local)
        self.assertEqual(b.merge(base, remote, local, ['xbox:95'], 'remote')[0], remote)

    def test_reset_and_concurrent_new_field(self):
        base = {'xbox:95': {'WheelX': 0}}
        remote = {'xbox:95': {'WheelX': 0, 'MapX': 5}}
        self.assertEqual(b.merge(base, remote, {}, ['xbox:95'])[0], {'xbox:95': {'MapX': 5}})


class DiscoveryTests(unittest.TestCase):
    def discover(self, output, model=b'Quest 3', index=None):
        def run(args, **kwargs):
            return subprocess.CompletedProcess(args, 0, output if args[1:3] == ['devices', '-l'] else model, b'')
        with patch.object(b.subprocess, 'run', side_effect=run):
            return b.Device('adb', index)

    def test_no_eligible_device(self):
        for output, model in [(b'List of devices attached\n', b''),
                              (b'List of devices attached\ntest-target unauthorized\n', b'Quest 3'),
                              (b'List of devices attached\ntest-target device\n', b'Unrelated phone'),
                              (b'List of devices attached\ntest-target offline\n', b'Quest 3')]:
            with self.assertRaises(b.BridgeError) as error:
                self.discover(output, model)
            self.assertNotIn('test-target', str(error.exception))

    def test_multiple_devices_require_selection(self):
        output = b'List of devices attached\ntest-one device\ntest-two device\n'
        with self.assertRaises(b.BridgeError):
            self.discover(output)
        self.assertEqual(self.discover(output, index=2).serial, 'test-two')

    def test_missing_adb_sanitized(self):
        with patch.object(b.subprocess, 'run', side_effect=OSError('sensitive transport output')):
            with self.assertRaises(b.BridgeError) as error:
                b.Device('adb')
        self.assertNotIn('sensitive', str(error.exception))


class TransferTests(unittest.TestCase):
    def device(self, remote=b.EMPTY.encode()):
        d = object.__new__(b.Device)
        d.files = {b.FILES['personal']: remote}
        d.commands = []
        d.running = False
        d.corrupt = False
        def run(*args, check=True):
            d.commands.append(args)
            if args[0] == 'push':
                d.files[args[2].split('/')[-1]] = b'corrupt' if d.corrupt else Path(args[1]).read_bytes()
            elif args[:1] == ('shell',):
                cmd = args[1]
                if cmd.startswith('if pidof'):
                    return subprocess.CompletedProcess(args, 0, b'RUNNING' if d.running else b'STOPPED', b'')
                if cmd.startswith('cp '):
                    _, src, dst = cmd.split()
                    d.files[dst.split('/')[-1]] = d.files[src.split('/')[-1]]
                if cmd.startswith('mv '):
                    _, src, dst = cmd.split()
                    d.files[dst.split('/')[-1]] = d.files.pop(src.split('/')[-1])
                if cmd.startswith('rm -f '):
                    d.files.pop(cmd.split('/')[-1], None)
            return subprocess.CompletedProcess(args, 0, b'', b'')
        d.run = run
        d.read = lambda name: d.files.get(name)
        return d

    def test_verified_install_keeps_backup(self):
        d = self.device()
        text = b.serialize({'xbox:95': {'WheelX': 5}})
        d.install(b.FILES['personal'], text, b.EMPTY.encode())
        self.assertEqual(d.files[b.FILES['personal']], text.encode())
        backups = [v for k, v in d.files.items() if '.backup-' in k]
        self.assertEqual(backups, [b.EMPTY.encode()])
        self.assertFalse(any(k.endswith('.upload') for k in d.files))

    def test_live_install_and_acknowledgement(self):
        d = self.device()
        d.running = True
        text = b.serialize({'xbox:106': {'RadioRoll': 61.64}})
        d.install(b.FILES['personal'], text, b.EMPTY.encode(), live=True)
        self.assertEqual(d.files[b.FILES['personal']], text.encode())
        read = d.read
        def status(name):
            if name == 'vehicle_placements.live.ini':
                nonce = d.files.get('vehicle_placements.reload', b'').decode()
                return f'[LivePlacement]\nVersion=1\nRequest={nonce}\npersonal={b.content_hash(text.encode())}\n'.encode()
            return read(name)
        d.read = status
        self.assertTrue(d.acknowledge('personal', text))
        d.running = False
        self.assertFalse(d.acknowledge('personal', text))

    def test_missing_live_acknowledgement_is_failure(self):
        d = self.device(); d.running = True
        with patch.object(b.time, 'monotonic', side_effect=[0, 11]):
            with self.assertRaises(b.BridgeError):
                d.acknowledge('personal', b.EMPTY)

    def test_failed_upload_preserves_destination(self):
        d = self.device()
        d.corrupt = True
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b.EMPTY.encode())
        self.assertEqual(d.files, {b.FILES['personal']: b.EMPTY.encode()})

    def test_running_game_and_changed_destination(self):
        d = self.device()
        d.running = True
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b.EMPTY.encode())
        d.running = False
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b'old contents')
        self.assertFalse(any(c[0] == 'push' for c in d.commands))

    def test_interrupted_upload(self):
        d = self.device()
        original = d.run
        def run(*args, **kwargs):
            if args[0] == 'push':
                raise b.BridgeError('Device operation failed')
            return original(*args, **kwargs)
        d.run = run
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b.EMPTY.encode())
        self.assertEqual(d.files[b.FILES['personal']], b.EMPTY.encode())

    def test_restore_backup_and_preserve_current(self):
        d = self.device(b.serialize({'xbox:95': {'WheelX': 12}}).encode())
        name = b.FILES['personal'] + '.backup-20261024T120000123456Z'
        d.files[name] = b.serialize({'xbox:95': {'WheelX': 5}}).encode()
        with patch.object(b, 'Device', return_value=d), contextlib.redirect_stdout(io.StringIO()):
            self.assertEqual(b.main(['restore', '--workspace', '.', '--backup', name]), 0)
        self.assertEqual(b.parse(d.files[b.FILES['personal']].decode()), {'xbox:95': {'WheelX': 5}})
        self.assertTrue(any(b'WheelX=12' in v for k, v in d.files.items() if '.backup-' in k))


if __name__ == '__main__':
    unittest.main()

